for (const item of $input.all()) {
  // Obtener el wa_id original
  const texto = $('Verifica quien escribe').first().json.mensaje_usuario_tel
  const wa_id = texto.split("@")[0];
  const wa_id_2 = texto.split("@")[0].slice(3);
  // Agregar el wa_id procesado al JSON
  item.json.processed_wa_id = wa_id;
  item.json.processed_wa_id_2 = wa_id_2;
}

// Devolver el array modificado
return $input.all();
